// ../shared/dist/schemas/audit.js
import { z as z6 } from "zod";

// ../shared/dist/constants.js
var AUDIT_VERDICTS = ["GO", "CONDITIONAL_GO", "REFINE", "KILL"];
var DEALBREAKER_ZONES = ["Star", "Green", "Yellow", "Orange", "Red"];
var AUDIT_LENSES = [
  "market-research",
  "competition",
  "problem-solution-fit",
  "team",
  "traction",
  "business-model",
  "gtm-scale",
  "finance",
  "mission",
  "dealbreakers"
];

// ../shared/dist/schemas/audit.js
var AuditStatusSchema = z6.enum([
  "pending",
  "in_progress",
  "completed",
  "failed",
  "cancelled"
]);
var AuditVerdictSchema = z6.enum(AUDIT_VERDICTS);
var DealbreakerZoneSchema = z6.enum(DEALBREAKER_ZONES);
var AuditLensNameSchema = z6.enum(AUDIT_LENSES);
var LensClaimSchema = z6.object({
  /** The assertion in the lens's own words. */
  text: z6.string().min(1).max(500),
  /**
   * `quantitative` claims carry a comparable `value` — those are the ones a
   * rule engine can contradict deterministically. `qualitative` claims are
   * judgements and stay the LLM's business.
   */
  kind: z6.enum(["quantitative", "qualitative"]),
  /** What the claim is about — a market, company, fund, or the idea itself. */
  subject: z6.string().min(1).max(200),
  /** Normalised relation, e.g. 'tam_usd', 'cagr_pct', 'raised_usd', 'headcount'. */
  predicate: z6.string().min(1).max(100),
  /** Comparable value for quantitative claims; omitted for qualitative ones. */
  value: z6.union([z6.number(), z6.string()]).optional(),
  /** Unit for `value`, e.g. 'usd', 'pct', 'people'. */
  unit: z6.string().max(32).optional(),
  /** When the claim started being true — a report year, a funding date. */
  validFrom: z6.string().datetime().optional(),
  /** URLs backing the claim. Empty means the lens asserted it unsupported. */
  sources: z6.array(z6.string().url()).max(20).default([]),
  /** True when the claim rests on data actually fetched by a tool call. */
  grounded: z6.boolean(),
  /** How sure the lens is of this specific claim. */
  score: z6.number().min(0).max(1)
});
var AuditSchema = z6.object({
  id: z6.string().uuid(),
  userId: z6.string().uuid(),
  title: z6.string(),
  inputText: z6.string(),
  status: AuditStatusSchema,
  verdict: AuditVerdictSchema.nullable(),
  zone: DealbreakerZoneSchema.nullable(),
  score: z6.number().min(0).max(100).nullable(),
  finalMd: z6.string().nullable(),
  createdAt: z6.string().datetime(),
  completedAt: z6.string().datetime().nullable()
});
var AuditLensSchema = z6.object({
  id: z6.string().uuid(),
  auditId: z6.string().uuid(),
  lensName: AuditLensNameSchema,
  markdown: z6.string(),
  rubricJson: z6.record(z6.string(), z6.unknown()),
  passed: z6.boolean(),
  createdAt: z6.string().datetime()
});
var OriginRefSchema = z6.object({
  url: z6.string().url().max(2048),
  kind: z6.enum([
    "reddit",
    "hn",
    "yc_launch",
    "rss",
    "manual",
    "discovered_idea",
    "digest_card"
  ]),
  attribution: z6.string().max(200).optional(),
  quote: z6.string().max(500).optional(),
  captured_at: z6.string().datetime().optional()
});
var SaveAuditInput = z6.object({
  title: z6.string().min(1).max(300),
  inputText: z6.string().min(1).max(5e4),
  /** Where this idea came from. Drives the audit's "References" section
   *  in the final report and the dashboard provenance panel. */
  originRefs: z6.array(OriginRefSchema).max(20).optional(),
  /**
   * Crossed-product audit — when the founder's observer profile is
   * pinned at save time, the audit row records it so downstream
   * dealbreakers / similar-audits / dashboard rendering can stay
   * observer-relative without a second lookup.
   *
   * Imported as a loose record here to avoid a circular import with
   * `observer-profile.ts`; the API handler narrows it through
   * `ObserverProfileSchema.optional()` before persisting.
   */
  observerContext: z6.record(z6.string(), z6.unknown()).optional()
});
var SaveLensOutputInput = z6.object({
  auditId: z6.string().uuid(),
  lensName: AuditLensNameSchema,
  markdown: z6.string(),
  rubricJson: z6.record(z6.string(), z6.unknown()).default({}),
  passed: z6.boolean(),
  /**
   * Checkable assertions extracted from `markdown`. Optional and defaulted so
   * older skill bundles keep working — a lens that sends none falls back to
   * citation-count confidence, exactly as before.
   */
  claims: z6.array(LensClaimSchema).max(50).default([])
});
var FinalizeAuditInput = z6.object({
  auditId: z6.string().uuid(),
  verdict: AuditVerdictSchema,
  zone: DealbreakerZoneSchema,
  score: z6.number().min(0).max(100),
  finalMd: z6.string()
});

