// dist/specs/_crossed-input.js
import { z as z13 } from "zod";
var LensKeyEnum = z13.enum([
  "team",
  "problem_solution",
  "traction",
  "competition",
  "gtm",
  "finance"
]);
var StageEnum = z13.enum(["idea", "mvp", "seed", "series_a_plus"]);
var crossedInputSchema = z13.object({
  stage: StageEnum,
  /**
   * Optional per-stage probabilities. When provided, the math blends
   * STAGE_WEIGHTS by these probabilities (the sum is normalised internally),
   * which is how an idea that is half-way to an MVP gets weights that are
   * also half-way rather than snapped to one bucket.
   */
  stageProbabilities: z13.object({
    idea: z13.number().min(0).max(1).optional(),
    mvp: z13.number().min(0).max(1).optional(),
    seed: z13.number().min(0).max(1).optional(),
    series_a_plus: z13.number().min(0).max(1).optional()
  }).optional(),
  sector: z13.string().min(1).max(80).optional(),
  lensScores: z13.array(z13.object({
    lens: LensKeyEnum,
    score: z13.number().min(0).max(100),
    confidence: z13.number().min(0).max(1),
    redFlag: z13.boolean().default(false)
  })).min(1).max(20),
  unresolvedContradictions: z13.number().int().min(0).max(20).default(0),
  hasMajorContradiction: z13.boolean().default(false),
  /**
   * Founder profile. When supplied, the math additionally produces an
   * observer-relative verdict — perturbed weights and risk-tolerance shifted
   * thresholds — alongside the substrate one. The KILL gate is deliberately
   * observer-invariant: fatal stays fatal for everyone.
   */
  observer: ObserverProfileSchema.optional()
});
var crossedJsonProperties = {
  stage: { type: "string", enum: ["idea", "mvp", "seed", "series_a_plus"] },
  sector: { type: "string" },
  lensScores: {
    type: "array",
    items: {
      type: "object",
      required: ["lens", "score", "confidence"],
      properties: {
        lens: {
          type: "string",
          enum: ["team", "problem_solution", "traction", "competition", "gtm", "finance"]
        },
        score: { type: "number", minimum: 0, maximum: 100 },
        confidence: { type: "number", minimum: 0, maximum: 1 },
        redFlag: { type: "boolean" }
      }
    }
  },
  stageProbabilities: {
    type: "object",
    properties: {
      idea: { type: "number", minimum: 0, maximum: 1 },
      mvp: { type: "number", minimum: 0, maximum: 1 },
      seed: { type: "number", minimum: 0, maximum: 1 },
      series_a_plus: { type: "number", minimum: 0, maximum: 1 }
    }
  },
  unresolvedContradictions: { type: "integer", minimum: 0, default: 0 },
  hasMajorContradiction: { type: "boolean", default: false },
  observer: {
    type: "object",
    description: "Founder profile that crosses with the substrate idea to produce an observer-relative verdict. When omitted, only the substrate verdict is returned.",
    required: ["founder_type"],
    properties: {
      founder_type: {
        type: "string",
        enum: ["solo", "cofounded_technical", "cofounded_business", "domain_expert", "serial"]
      },
      runway_months: { type: "integer", minimum: 0, maximum: 60 },
      capital_usd_band: { type: "string", enum: ["under_50k", "50k_500k", "500k_5m", "over_5m"] },
      risk_tolerance: { type: "string", enum: ["conservative", "moderate", "aggressive"] },
      expertise_sectors: {
        type: "array",
        maxItems: 8,
        items: { type: "string", minLength: 2, maxLength: 80 }
      },
      time_horizon_years: { type: "integer", minimum: 1, maximum: 15 },
      exit_goal: { type: "string", enum: ["lifestyle", "acquisition", "ipo", "unicorn"] }
    }
  }
};

// dist/specs/compute-dealbreakers-v2.js
function computeDealbreakersV2Crossed(i) {
  return computeCrossedDealbreakersV2(i, i.observer ?? null, i.sector);
}
function toDealbreakersV2Verdict(crossed) {
  return {
    ...crossed.substrateFull,
    substrate: crossed.substrate,
    crossed: crossed.crossed,
    delta: crossed.delta,
    archetypes: crossed.archetypes
  };
}
var computeDealbreakersV2Spec = defineSpec({
  name: "compute_dealbreakers_v2",
  description: "Methodology v2 dealbreakers \u2014 stage-aware weights + confidence-weighted lens scoring + risk-asymmetric verdict (GO requires score\u226580 AND zero red flags AND avg confidence\u22650.6). Optional `observer` triggers the crossed-product pipeline: substrate verdict (no-observer baseline) PLUS crossed verdict (observer-perturbed weights, risk-tolerance shifted thresholds) PLUS 5-row archetype matrix. The KILL gate (\u22652 blockers / score<50) is observer-invariant \u2014 fatal stays fatal.",
  schema: crossedInputSchema,
  jsonSchema: {
    type: "object",
    required: ["stage", "lensScores"],
    properties: crossedJsonProperties
  },
  fn: (i) => toDealbreakersV2Verdict(computeDealbreakersV2Crossed(i))
});

// dist/specs/compute-crossed-matrix.js
var computeCrossedMatrixSpec = defineSpec({
  name: "compute_crossed_matrix",
  description: 'Crossed-product audit explorer. Same input as compute_dealbreakers_v2 \u2014 returns substrate verdict (no-observer baseline) + crossed verdict (when observer supplied) + a 5-row matrix of {solo, cofounded_technical, cofounded_business, domain_expert, serial} archetype verdicts. Never persists; meant for the dashboard "view as [archetype]" dropdown and for previewing a verdict before committing to it.',
  schema: crossedInputSchema,
  jsonSchema: {
    type: "object",
    required: ["stage", "lensScores"],
    properties: crossedJsonProperties
  },
  fn: (i) => computeDealbreakersV2Crossed(i)
});

