import { z as z21 } from "zod";
var Input12 = z21.object({
  trendsTimelineValues: z21.array(z21.number().min(0).max(100)).max(120),
  externalVolumeNorm: z21.number().min(0).max(1),
  intentNorm: z21.number().min(0).max(1),
  geoSpreadNorm: z21.number().min(0).max(1),
  daysSinceLastSignal: z21.number().min(0).optional()
});
var computeSearchVelocityV2Spec = defineSpec({
  name: "compute_search_velocity_v2",
  description: "Search velocity (0-25) v2 \u2014 canonical 0.40*volume + 0.30*trend + 0.20*intent + 0.10*geo. CRITICAL: externalVolumeNorm MUST come from external sources (Amazon BSR / app store installs / job-board postings) \u2014 NOT the Trends timeline (would double-count, since Trends is itself normalized 0-100 within window). trendNorm is derived internally from trendsTimelineValues. Trends peak<50 zeroes the trend component (Yotpo SEO floor). Optional daysSinceLastSignal applies exponential freshness decay (search half-life 90d).",
  schema: Input12,
  jsonSchema: {
    type: "object",
    properties: {
      trendsTimelineValues: {
        type: "array",
        items: { type: "number", minimum: 0, maximum: 100 },
        description: "Monthly Trends values 0-100. Used ONLY to derive trendNorm \u2014 never as raw volume."
      },
      externalVolumeNorm: {
        type: "number",
        minimum: 0,
        maximum: 1,
        description: "Normalized 0-1 demand volume from EXTERNAL sources (Amazon, app stores, jobs). Caller normalizes before passing."
      },
      intentNorm: { type: "number", minimum: 0, maximum: 1, description: "0-1 commercial/transactional intent ratio." },
      geoSpreadNorm: { type: "number", minimum: 0, maximum: 1, description: "0-1 geographic spread (regions with interest > threshold)." },
      daysSinceLastSignal: {
        type: "number",
        minimum: 0,
        description: "Optional: days since most recent confirming signal. Triggers exponential freshness decay (half-life 90d)."
      }
    },
    required: ["trendsTimelineValues", "externalVolumeNorm", "intentNorm", "geoSpreadNorm"]
  },
  fn: (i) => computeSearchVelocityV2(i)
});

