// dist/server.js
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { CallToolRequestSchema, ListToolsRequestSchema } from "@modelcontextprotocol/sdk/types.js";
import { createRequire } from "node:module";
var VERSION = createRequire(import.meta.url)("../package.json").version;
function unknownArgs(spec, args) {
  if (args === null || typeof args !== "object" || Array.isArray(args))
    return [];
  const declared = spec.jsonSchema.properties;
  if (declared === null || typeof declared !== "object")
    return [];
  const known = new Set(Object.keys(declared));
  return Object.keys(args).filter((k) => !known.has(k));
}
async function main() {
  const server = new Server({ name: "ideaudit-tools", version: VERSION }, { capabilities: { tools: {} } });
  server.setRequestHandler(ListToolsRequestSchema, async () => ({
    tools: ALL_SPECS.map((s) => ({
      name: s.name,
      description: s.description,
      inputSchema: s.jsonSchema
    }))
  }));
  server.setRequestHandler(CallToolRequestSchema, async (req) => {
    const spec = ALL_SPECS.find((s) => s.name === req.params.name);
    if (!spec) {
      return {
        isError: true,
        content: [{ type: "text", text: `Unknown tool: ${req.params.name}` }]
      };
    }
    const unknown = unknownArgs(spec, req.params.arguments);
    if (unknown.length > 0) {
      return {
        isError: true,
        content: [
          {
            type: "text",
            text: JSON.stringify({
              error: "unknown_arguments",
              unknown,
              message: "This server computes; it stores nothing. Arguments that name something to save are only honoured by the hosted server at https://api.inite.studio/mcp."
            }, null, 2)
          }
        ]
      };
    }
    const parsed = spec.schema.safeParse(req.params.arguments ?? {});
    if (!parsed.success) {
      return {
        isError: true,
        content: [
          {
            type: "text",
            text: JSON.stringify({ error: "invalid_input", detail: parsed.error.issues }, null, 2)
          }
        ]
      };
    }
    try {
      const result = spec.fn(parsed.data);
      return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
    } catch (err) {
      return {
        isError: true,
        content: [
          {
            type: "text",
            text: JSON.stringify({ error: "tool_failed", message: err instanceof Error ? err.message : String(err) }, null, 2)
          }
        ]
      };
    }
  });
  await server.connect(new StdioServerTransport());
}
